//! URL parsing/building library mirroring the C++ `url_parser` behavior
//! inferred from the reference binary.

/// Mimics `std::stoi` (base 10): skips leading whitespace, accepts an
/// optional sign, parses the leading run of digits (ignoring any trailing
/// junk), and aborts on invalid input or on values outside the `int` range.
pub fn stoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;

    // Skip leading whitespace (C locale isspace).
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    if i >= bytes.len() || !bytes[i].is_ascii_digit() {
        stoi_fail("invalid_argument");
    }

    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
        i += 1;
    }

    let limit = if negative {
        2147483648i64 // -2147483648 is INT_MIN
    } else {
        2147483647i64
    };
    if value > limit {
        stoi_fail("out_of_range");
    }

    if negative {
        -(value as i32)
    } else {
        value as i32
    }
}

/// Reproduces the C++ program's uncaught-exception termination.
fn stoi_fail(kind: &str) -> ! {
    eprintln!("terminate called after throwing an instance of 'std::{}'", kind);
    eprintln!("  what():  stoi");
    std::process::abort();
}

pub struct URL {
    scheme: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl URL {
    pub fn from_components(
        scheme: &str,
        host: &str,
        port: i32,
        path: &str,
        query: &str,
        fragment: &str,
    ) -> URL {
        // Ports outside 0..=65535 become -1 (meaning "no port").
        let port = if (0..=65535).contains(&port) { port } else { -1 };
        // A non-empty path is forced to start with '/'.
        let path = if !path.is_empty() && !path.starts_with('/') {
            format!("/{}", path)
        } else {
            path.to_string()
        };
        URL {
            scheme: scheme.to_string(),
            host: host.to_string(),
            port,
            path,
            query: query.to_string(),
            fragment: fragment.to_string(),
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn to_string(&self) -> String {
        let mut out = String::new();
        // The scheme://host:port prefix is only emitted when the scheme is
        // non-empty; the port is only emitted when it is set (>= 0).
        if !self.scheme.is_empty() {
            out.push_str(&self.scheme);
            out.push_str("://");
            out.push_str(&self.host);
            if self.port >= 0 {
                out.push(':');
                out.push_str(&self.port.to_string());
            }
        }
        out.push_str(&self.path);
        if !self.query.is_empty() {
            out.push('?');
            out.push_str(&self.query);
        }
        if !self.fragment.is_empty() {
            out.push('#');
            out.push_str(&self.fragment);
        }
        out
    }

    pub fn is_valid(&self) -> bool {
        !self.host.is_empty() || !self.path.is_empty()
    }
}

